insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('f00fc145-d8c6-5c44-ad4d-11790970e779', 'apy', 'central', null, 'pension', 'https://pfrda.org.in/w/faqs/atal-pension-yojana', 'sha256:4885a90758043facfd65e4f8c2a0eafd9fb5b9ab2d96e831562dd80f8011789f', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('f00fc145-d8c6-5c44-ad4d-11790970e779', 'en', 'Atal Pension Yojana', 'Guaranteed monthly pension in old age in return for regular contributions.', 'Go to the bank branch or post office where you have a savings account (open one if you don''t) and enrol there; the contribution is auto-debited from that account.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('60bbbf39-1db1-5593-a3d2-e54047b11fb3', 'f00fc145-d8c6-5c44-ad4d-11790970e779', 1, 1, '{"all": [{"field": "age", "op": "gte", "value": 18, "source_quote": "The age of an individual should be between 18 and 40 years."}, {"field": "age", "op": "lt", "value": 40, "source_quote": "A person can join APY till his/ her 40th birthday."}]}'::jsonb, '[{"text": "Must have a savings bank or post office savings account", "source_quote": "He / She should have a savings bank account/ post office savings bank account."}, {"text": "Must not be, or have been, an income-tax payer (for accounts opened from 1 Oct 2022)", "source_quote": "any Indian citizen who is or has been an income-tax payer under the Income-tax Act, 1961, as on the date of application will not be eligible to open a new APY account."}, {"text": "Must be a citizen of India", "source_quote": "APY is open to all citizens of India"}, {"text": "Only one APY account per person", "source_quote": "An individual can open only one APY account."}]'::jsonb, '["The eligibility list says ''between 18 and 40 years'', but the FAQ says joining is allowed only until the 40th birthday. In completed years that means 18 to 39 (a person on the exact day of their 40th birthday can still join)."]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('a8e9ffd0-2b48-51ef-8d35-a7f963f83636', 'e-shram', 'central', null, 'livelihood', 'https://wb.gov.in/government-schemes-details-e-shram-card.aspx', 'sha256:1185436f7a6b446a88a7b05aa5abed96d62fa20d6c10df2376f4b5bc46b5be68', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('a8e9ffd0-2b48-51ef-8d35-a7f963f83636', 'en', 'e-Shram Card', 'A 12-digit UAN card for unorganised workers that links to accident cover (PMSBY), pension (PM-SYM) and other schemes.', 'Register free on the e-Shram portal or at a Common Service Centre with Aadhaar, its linked mobile number and bank details.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('72b207d8-8127-5674-8f7c-edee228c9e20', 'a8e9ffd0-2b48-51ef-8d35-a7f963f83636', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [16, 59], "source_quote": "Age should be between 16 and 59 years."}]}'::jsonb, '[{"text": "Must be an Indian citizen", "source_quote": "Must be an Indian citizen."}, {"text": "Must work in the unorganised sector (construction, street vending, domestic work, migrant work, etc.)", "source_quote": "Must be a worker in the unorganized sector (e.g., construction workers, street vendors, domestic workers, migrant workers, etc.)."}, {"text": "Must not be a member of EPFO, ESIC or government-funded NPS", "source_quote": "Should not be a member of EPFO, ESIC, or NPS (government-funded)."}, {"text": "Must be self-employed, home-based or a wage worker in informal work", "source_quote": "Should be a self-employed worker, home-based worker, or wage worker in informal employment."}, {"text": "Meant mainly for low-income workers (no strict limit is stated)", "source_quote": "Generally intended for workers with lower or unstable income (typically below Rs 15,000/month for certain linked schemes)."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "The income line is guidance (''generally intended''), not a firm limit"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('e9de7372-b08b-5c4c-8b84-0c5c5f6e81fe', 'igndps', 'central', null, 'pension', 'https://sjsa.maharashtra.gov.in/en/scheme/indira-gandhi-national-disability-pension-scheme/', 'sha256:645eecb0d966fb358577e7494aa0e9c9f826f50e037c51348f622df6630bed86', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('e9de7372-b08b-5c4c-8b84-0c5c5f6e81fe', 'en', 'Indira Gandhi National Disability Pension Scheme', 'Rs 300 per month from the Centre.', 'Apply at the Collector''s office, Tehsildar''s office (Sanjay Gandhi Niradhar Anudan Yojana branch) or Talathi office.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('f543375e-275c-5bc2-bb32-ccb009176576', 'e9de7372-b08b-5c4c-8b84-0c5c5f6e81fe', 1, 1, '{"all": [{"field": "disability_percent", "op": "gt", "value": 0, "source_quote": "A Disable person in the age group of 18 to 79 years"}, {"field": "age", "op": "between", "value": [18, 79], "source_quote": "A Disable person in the age group of 18 to 79 years"}]}'::jsonb, '[]'::jsonb, '["This page gives no minimum disability percentage and does not mention BPL; national guidelines add both (not on this page)"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('dbc87b11-b5ba-5189-842a-4489fefaa311', 'ignoaps', 'central', null, 'pension', 'https://sjsa.maharashtra.gov.in/en/scheme/indira-gandhi-national-old-age-pension-scheme/', 'sha256:25d63f2ebb9f0f0a51ac0a011a18499e86f90bda88cfb967c845d2e23c7b6f9b', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('dbc87b11-b5ba-5189-842a-4489fefaa311', 'en', 'Indira Gandhi National Old Age Pension Scheme', 'Rs 200 per month (65 to 79) or Rs 500 (80+) from the Centre, plus a state top-up under the Shravanbal scheme in Maharashtra.', 'Apply at the Collector''s office, Tehsildar''s office (Sanjay Gandhi Niradhar Anudan Yojana branch) or Talathi office.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('e9b94046-eaaf-5a3d-bd9d-398e6b48553b', 'dbc87b11-b5ba-5189-842a-4489fefaa311', 1, 1, '{"all": [{"field": "age", "op": "gte", "value": 65, "source_quote": "Eligible elderly individuals aged 65 and above"}, {"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "whose names are on the Below Poverty Line (BPL) list"}]}'::jsonb, '[]'::jsonb, '["This state page says 65 and above; the national NSAP rule has been 60 and above since 2011 (not on this page)"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('480a243f-188b-5e8d-bf80-4de99bca9686', 'ignwps', 'central', null, 'pension', 'https://sjsa.maharashtra.gov.in/en/scheme/indira-gandhi-national-widow-pension-scheme/', 'sha256:36956459d0f3f5bc78d4f81baadc686718e9536538cc4f2ad8927d4763a9a939', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('480a243f-188b-5e8d-bf80-4de99bca9686', 'en', 'Indira Gandhi National Widow Pension Scheme', 'Rs 300 per month from the Centre; with the state top-up, Rs 1,500 per month in Maharashtra.', 'Apply at the Collector''s office, Tehsildar''s office (Sanjay Gandhi Niradhar Anudan Yojana branch) or Talathi office.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('7584ae8b-6a45-5e09-b53f-941c81ac38b6', '480a243f-188b-5e8d-bf80-4de99bca9686', 1, 1, '{"all": [{"field": "marital_status", "op": "eq", "value": "widow", "source_quote": "A widow in age group of 40 to 79 years"}, {"field": "age", "op": "between", "value": [40, 79], "source_quote": "A widow in age group of 40 to 79 years"}, {"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "whose family falls under Below Poverty Line"}]}'::jsonb, '[]'::jsonb, '["Other sources give the age band as 40 to 59; this page says 40 to 79", "''Family falls under Below Poverty Line'' is modelled as holding a BPL card"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('251f2897-78ea-59e6-9188-63eefea81ce5', 'mh-ladki-bahin', 'state', 'MH', 'women', 'https://www.womenchild.maharashtra.gov.in/en/schemes/mukhyamantri-mazi-ladki-bahin-yojana', 'sha256:0a71b9122b3cb373bffc91e568a51629778fca05c19dd5f89bc7e103ada15da5', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('251f2897-78ea-59e6-9188-63eefea81ce5', 'en', 'Mukhyamantri Mazi Ladki Bahin Yojana', 'Rs 1,500 per month by direct bank transfer.', 'Apply on the official website, ladakibahin.maharashtra.gov.in.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('7ba49013-8687-58e5-a41c-5f5297b80eb1', '251f2897-78ea-59e6-9188-63eefea81ce5', 1, 1, '{"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "providing ₹1,500 per month to eligible women across the state"}, {"field": "age", "op": "between", "value": [21, 65], "source_quote": "It targets state residents between 21 and 65 years of age"}, {"field": "annual_family_income", "op": "lt", "value": 250000, "source_quote": "with an annual family income of less than ₹2.5 lakh"}]}'::jsonb, '[]'::jsonb, '["This is an overview page; the Government Resolution''s full exclusion list (e.g. tax payers, government employees) is not on it", "The page says ''between 21 and 65 years of age'' without saying whether a 65-year-old qualifies; the rule treats 65 as included until the Government Resolution text is checked (step 2b)"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('ab5459d4-21ff-51fc-9247-74c12ca3ad00', 'mh-post-matric-sc', 'state', 'MH', 'education', 'https://sjsa.maharashtra.gov.in/en/scheme/post-matric-scholarship-by-the-government-of-india/', 'sha256:6a5156d06a2106722aa51f74a1d870f6ed4b3580a9a5170f430f560f90f8c620', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('ab5459d4-21ff-51fc-9247-74c12ca3ad00', 'en', 'Post-Matric Scholarship for SC Students (Maharashtra)', 'Maintenance allowance (Rs 250 to Rs 700 a month; Rs 400 to Rs 1,350 for hostel students) plus tuition, exam and other approved fees.', 'Fill the online form on mahadbtmahait.gov.in; contact your college or the district Assistant Commissioner of Social Welfare.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('dc696191-5574-5203-9752-7466606626d9', 'ab5459d4-21ff-51fc-9247-74c12ca3ad00', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "SC", "source_quote": "The student must belong to Scheduled Castes (SC) or Neo-Buddhist categories."}, {"field": "annual_family_income", "op": "lte", "value": 250000, "source_quote": "The annual income of the student’s parents should be ₹2.5 lakh or less."}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "The student should be pursuing education after the matriculation examination."}, {"field": "education_level", "op": "in", "value": ["class_11", "class_12", "diploma", "undergraduate", "postgraduate"], "source_quote": "The student should be pursuing education after the matriculation examination."}]}'::jsonb, '[{"text": "Must be a resident of Maharashtra (the app checks the state; proof is still needed)", "source_quote": "The student should be a resident of Maharashtra."}]'::jsonb, '["Neo-Buddhist applicants are eligible too, but the app has no Neo-Buddhist category, so they must answer SC (Buddhists are in the SC order since 1990; this page does not say so)", "''After the matriculation examination'' is mapped to class 11, class 12, diploma, undergraduate and postgraduate", "The income limit is for the student''s parents; the app asks annual family income"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('51763084-f4e0-5bb6-9e05-709fc8916ab2', 'mh-ramai-awas', 'state', 'MH', 'housing', 'https://sjsa.maharashtra.gov.in/en/scheme/ramai-housing-scheme-rural-and-urban/', 'sha256:96a56b3b618b301a56e6e75eb567fc4c27efe27651266e227b7c9e2d171387fd', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('51763084-f4e0-5bb6-9e05-709fc8916ab2', 'en', 'Ramai Awas Yojana (Rural and Urban)', 'Help to build a house: Rs 1.32 lakh rural, Rs 1.42 lakh hill/Naxal areas, Rs 2.50 lakh urban (beneficiary pays 7.5% to 10% in urban areas).', 'Contact the Assistant Commissioner of Social Welfare of your district.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('a9e69aff-e174-5308-9aef-73cb554b4c81', '51763084-f4e0-5bb6-9e05-709fc8916ab2', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "SC", "source_quote": "The applicant must belong to the Scheduled Castes/Neo-Buddhist category."}]}'::jsonb, '[{"text": "Must have lived in Maharashtra for at least 15 years", "source_quote": "The applicant must have resided in Maharashtra for at least 15 years."}, {"text": "Must own land or a temporary house", "source_quote": "The beneficiary must own land/a temporary house."}, {"text": "Must not have received a house under any other housing scheme", "source_quote": "The beneficiary should not have availed of any other housing scheme previously."}, {"text": "Must not be on the SECC-2011 priority list (those families are covered by other housing schemes)", "source_quote": "The beneficiary should be outside the priority list criteria of the Social, Economic, and Caste Census-2011 (SECC-2011)."}, {"text": "Protected hutment dwellers on government land (as of 1.01.1995) need not submit the 7/12 land extract", "source_quote": "the requirement to submit 7/12 extract has been relaxed"}, {"text": "Family income limit depends on the area: Rs 1.20 lakh in rural and hill/Naxal-affected areas, Rs 3.00 lakh in municipal councils and corporations", "source_quote": "Income Limit (in lakhs)"}]'::jsonb, '["Neo-Buddhist applicants are eligible too, but the app has no Neo-Buddhist category, so they must answer SC (Buddhists are in the SC order since 1990; this page does not say so)", "The income limit depends on rural or urban area, and the app has no such field, so it is not modelled", "The table does not say whether the income limit is per year; read as annual family income"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('381fba56-f240-5527-a2ee-0c9632e92642', 'mh-sanjay-gandhi-niradhar', 'state', 'MH', 'pension', 'https://sjsa.maharashtra.gov.in/en/scheme/sanjay-gandhi-niradhar-anudan-yojana/', 'sha256:3615efc7e9160e22e9e4f0385bc940284e574ff1c098f57633e229877bcdcdb0', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('381fba56-f240-5527-a2ee-0c9632e92642', 'en', 'Sanjay Gandhi Niradhar Anudan Yojana', 'Rs 1,500 per month.', 'Apply at the District Collector''s office, Tehsildar''s office (Sanjay Gandhi Niradhar Anudan Yojana branch) or Talathi office.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('5595d516-e207-5ea2-89ea-9582754cb275', '381fba56-f240-5527-a2ee-0c9632e92642', 1, 1, '{"all": [{"any": [{"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "the beneficiary’s name must be on the Below Poverty Line (BPL) list"}, {"field": "annual_family_income", "op": "lte", "value": 21000, "source_quote": "the family’s annual income must be up to ₹21,000"}]}, {"any": [{"field": "age", "op": "between", "value": [18, 65], "source_quote": "Destitute men and women aged 18 to 65 years"}, {"field": "disability_percent", "op": "gt", "value": 0, "source_quote": "All categories of disabled individuals"}, {"field": "marital_status", "op": "eq", "value": "widow", "source_quote": "Destitute widows"}, {"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "divorced women not receiving alimony"}, {"field": "marital_status", "op": "eq", "value": "divorced", "source_quote": "divorced women not receiving alimony"}]}, {"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "Unmarried women over 35 years of age"}, {"field": "marital_status", "op": "eq", "value": "single", "source_quote": "Unmarried women over 35 years of age"}, {"field": "age", "op": "gt", "value": 35, "source_quote": "Unmarried women over 35 years of age"}]}]}]}'::jsonb, '[{"text": "Must be destitute (no means of support); the 18 to 65 age band applies to destitute men and women", "source_quote": "Destitute men and women aged 18 to 65 years"}, {"text": "People unable to support themselves due to severe illness (TB, cancer, AIDS, leprosy)", "source_quote": "unable to sustain themselves due to severe illnesses such as tuberculosis, cancer, AIDS, leprosy"}, {"text": "Women who were victims of abuse or rescued from prostitution", "source_quote": "Women who have been victims of abuse or rescued from prostitution"}, {"text": "Wives of prisoners serving sentences", "source_quote": "Wives of prisoners serving sentences"}, {"text": "Women undergoing divorce proceedings", "source_quote": "Women undergoing divorce proceedings"}, {"text": "Orphaned children", "source_quote": "Orphaned children"}, {"text": "Transgender individuals", "source_quote": "Transgender individuals"}, {"text": "Devadasis", "source_quote": "Devadasis"}, {"text": "People suffering from sickle cell disease", "source_quote": "Individuals suffering from sickle cell disease"}]'::jsonb, '["''Destitute'' is not defined and is not modelled; the age band 18 to 65 may apply to all categories or only to destitute men and women", "''Not receiving alimony'' is not modelled", "Eight of the twelve listed categories are unmodelled, so a FAIL on the category group can be a false negative"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('0f070b6a-e52c-573f-a813-107c88db1f24', 'mh-sc-fee-reimbursement', 'state', 'MH', 'education', 'https://sjsa.maharashtra.gov.in/en/scheme/reimbursement-of-education-fees-and-examination-fees-for-backward-class-students/', 'sha256:6ef4f75917ff46761bf1b0de3832baa98f37beeaf40f6a6898d68299813e537e', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('0f070b6a-e52c-573f-a813-107c88db1f24', 'en', 'Education and Exam Fee Reimbursement for SC Students (Maharashtra)', 'Education fees, exam fees and other prescribed fees for recognised post-matric courses, paid to the college.', 'Apply online on mahadbtmahait.gov.in through your college; the district Assistant Commissioner of Social Welfare approves it.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('4fde7306-ef28-55fa-b2c6-246fed72d497', '0f070b6a-e52c-573f-a813-107c88db1f24', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "SC", "source_quote": "The student must belong to Scheduled Castes (SC) or Neo-Buddhist categories."}, {"field": "annual_family_income", "op": "gt", "value": 250000, "source_quote": "The annual income of the student’s parents should be more than ₹2.50 lakh."}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "The student should be pursuing education after the matriculation examination."}, {"field": "education_level", "op": "in", "value": ["class_11", "class_12", "diploma", "undergraduate", "postgraduate"], "source_quote": "The student should be pursuing education after the matriculation examination."}]}'::jsonb, '[{"text": "Must be a resident of Maharashtra (the app checks the state; proof is still needed)", "source_quote": "The student should be a resident of Maharashtra."}]'::jsonb, '["Neo-Buddhist applicants are eligible too, but the app has no Neo-Buddhist category, so they must answer SC (Buddhists are in the SC order since 1990; this page does not say so)", "''After the matriculation examination'' is mapped to class 11, class 12, diploma, undergraduate and postgraduate", "The income limit is for the student''s parents; the app asks annual family income"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('8c1d9734-b330-56a2-b317-51e4111b15b5', 'mh-shravanbal', 'state', 'MH', 'pension', 'https://nashik.gov.in/scheme/shravan-bal-seva-rajya-nivruttivetan-yojana/', 'sha256:ef72dfeffbaf17e4a1de8f1b8f31d53e670fbd3fc2f74de46720947612ac3ddb', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('8c1d9734-b330-56a2-b317-51e4111b15b5', 'en', 'Shravanbal Seva Rajya Nivruttivetan Yojana', 'Monthly state pension. This 2019 page says Rs 600 (category A) or Rs 400 plus Rs 200 under IGNOAPS (category B); the 2025 Nagpur district page says Rs 1,500.', 'Apply at the Collector''s office, Tahsildar or Talathi.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('b3ef4935-4444-5a90-8e15-a1055c09a78c', '8c1d9734-b330-56a2-b317-51e4111b15b5', 1, 1, '{"all": [{"field": "age", "op": "gte", "value": 65, "source_quote": "every destitute person of age 65 years & above"}, {"any": [{"all": [{"field": "annual_family_income", "op": "lt", "value": 21000, "source_quote": "whose annual family income is below Rs. 21000/-"}, {"field": "has_bpl_card", "op": "eq", "value": false, "source_quote": "whose name is not included in the BPL List"}]}, {"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "belonging to BPL family"}]}]}'::jsonb, '[{"text": "Must be destitute (niradhar)", "source_quote": "every destitute person"}]'::jsonb, '["Source is the Nashik district page, last updated 15.01.2019; the Nagpur district page (updated 11.09.2025) says Rs 1,500 a month, so the amounts here may be out of date", "''Name not included in the BPL List'' is modelled as not having a BPL card"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('e8d0f23c-6b2f-5e9c-919e-952f5bd48ff4', 'nfbs', 'central', null, 'family', 'https://sjsa.maharashtra.gov.in/en/scheme/national-family-benefit-scheme/', 'sha256:ead5bb809feef55ce38cf97128f2faf64f901e156790e511f865c074ad14a91c', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('e8d0f23c-6b2f-5e9c-919e-952f5bd48ff4', 'en', 'National Family Benefit Scheme', 'One-time lump sum of Rs 20,000 to the family.', 'Apply at the Collector''s office, Tehsildar''s office (Sanjay Gandhi Niradhar Anudan Yojana branch) or Talathi office.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('5fb1f0bd-4d8a-5a01-8c4a-b3ef6c4dabb9', 'e8d0f23c-6b2f-5e9c-919e-952f5bd48ff4', 1, 1, '{"all": [{"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "death of a primary bread winner in the BPL Family"}]}'::jsonb, '[{"text": "The family''s primary breadwinner has died (accident or natural causes)", "source_quote": "in case of accidental or natural death of a primary bread winner"}, {"text": "The breadwinner was aged 18 to 59 at the time of death", "source_quote": "in the age group of 18 to 59 years"}]'::jsonb, '[]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('6d241a78-6760-59b7-9e9e-2f33560ab935', 'pm-kisan', 'central', null, 'farming', 'https://pmkisan.gov.in/Documents/Revised%20Operational%20Guidelines%20-%20PM-Kisan%20Scheme.pdf', 'sha256:3d5138a963a0ae59a8f2085cbe5a407bed2cb89161ae14891643b443ed7f9d27', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('6d241a78-6760-59b7-9e9e-2f33560ab935', 'en', 'PM Kisan Samman Nidhi', 'Rs 6,000 per year paid directly into the bank account of eligible farmer families.', 'Beneficiaries are identified by the State or UT government from land records and uploaded to the PM-KISAN portal.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('421e7249-9ee5-5c74-ad07-e5079d4a9620', '6d241a78-6760-59b7-9e9e-2f33560ab935', 1, 1, '{"all": [{"field": "land_acres", "op": "gt", "value": 0, "source_quote": "all landholding farmers’ families in the country, having cultivable land"}]}'::jsonb, '[{"text": "Not an institutional land holder", "source_quote": "All Institutional Land holders"}, {"text": "No family member holds or held a constitutional post", "source_quote": "Former and present holders of constitutional posts"}, {"text": "No family member is or was a Minister, MP, MLA, MLC, Mayor or District Panchayat Chairperson", "source_quote": "Former and present Ministers/ State Ministers and former/present Members of Lok Sabha/ Rajya Sabha/ State Legislative Assemblies/ State Legislative Councils"}, {"text": "No family member is a serving or retired government or PSE employee (Group D / MTS excepted)", "source_quote": "All serving or retired officers and employees of Central/ State Government Ministries"}, {"text": "Not a person who paid income tax in the last assessment year", "source_quote": "All Persons who paid Income Tax in last assessment year."}, {"text": "Not a retired pensioner with monthly pension of Rs 10,000 or more", "source_quote": "All superannuated/retired pensioners whose monthly pension is Rs.10,000/-or more"}, {"text": "Not a practising registered professional (doctor, engineer, lawyer, CA, architect)", "source_quote": "Professionals like Doctors, Engineers, Lawyers, Chartered Accountants, and Architects registered with Professional bodies"}, {"text": "Land must be owned as per state land records", "source_quote": "who own cultivable land as per land records of the concerned State/UT"}]'::jsonb, '[]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('c6c004b5-6dba-58c8-8f0b-a2077b1b2f24', 'pm-sym', 'central', null, 'pension', 'https://wb.gov.in/government-schemes-details-pradhan-mantri-shram-yogi-mandhan.aspx', 'sha256:850c642197c46200e6f127eb517fcd8b1b64aaed0afa2da2b3331db19be0e17a', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('c6c004b5-6dba-58c8-8f0b-a2077b1b2f24', 'en', 'Pradhan Mantri Shram Yogi Maandhan', 'Pension of Rs 3,000 a month from age 60; the government matches your monthly contribution (Rs 55 to Rs 200).', 'Enrol at a Common Service Centre or online with Aadhaar and bank details; set up the monthly auto-debit.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('af514d7a-3bdd-5c4b-94f6-6233f7ad439e', 'c6c004b5-6dba-58c8-8f0b-a2077b1b2f24', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [18, 40], "source_quote": "Age should be between18 and 40 years at the time of enrollment."}]}'::jsonb, '[{"text": "Must be an unorganised-sector worker (street vendor, construction worker, domestic worker, etc.)", "source_quote": "Must be an unorganized sector worker (e.g., street vendors, construction workers, domestic workers, etc.)."}, {"text": "Own monthly income must be Rs 15,000 or less (the app asks family income per year, so this is not checked)", "source_quote": "Monthly income should be Rs 15,000 or less."}, {"text": "Must have an Aadhaar number linked to a mobile number", "source_quote": "Must possess a valid Aadhaar number linked with a mobile number."}, {"text": "Must have a savings bank or Jan Dhan account", "source_quote": "Should have anactive savings bank account or Jan Ohan account."}, {"text": "Must not be covered by EPFO, ESIC or NPS", "source_quote": "Must not be covered under any other statutory social security scheme (such as EPF0, ESIC,orNPS)."}, {"text": "Must not pay income tax", "source_quote": "Must not be an income taxpayer."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('7fb74b3a-89f5-5236-af15-2fb27234fb73', 'pm-vishwakarma', 'central', null, 'livelihood', 'https://wb.gov.in/government-schemes-details-pradhan-mantri-vishwakarma-yojana.aspx', 'sha256:58c2f37b534a91eb3ff486ccf85dacae471e9a2876b24ae808983f5ad6eff0ce', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('7fb74b3a-89f5-5236-af15-2fb27234fb73', 'en', 'PM Vishwakarma', 'Certificate and ID card, free training with Rs 500 a day, Rs 15,000 toolkit help, and collateral-free loans up to Rs 3 lakh at about 5%.', 'Register through the official PM Vishwakarma channel described on the source page.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('a540762e-6f8e-579d-93aa-76bb8c9c6735', '7fb74b3a-89f5-5236-af15-2fb27234fb73', 1, 1, '{"all": [{"field": "age", "op": "gte", "value": 18, "source_quote": "Must be 18 years or above at the time of registration"}]}'::jsonb, '[{"text": "Must be an artisan or craftsperson working with hands and tools in a notified trade", "source_quote": "Applicant must be an artisan or craftsperson working with hands and tools in one of the notified traditional trades"}, {"text": "Must be self-employed in the unorganised sector", "source_quote": "Should be self-employed in the unorganised sector"}, {"text": "Must work in one of the 18 family-based trades: carpenter, boat maker, armourer, blacksmith, hammer and toolkit maker, locksmith, sculptor, goldsmith, potter, cobbler, mason, basket/mat/broom/coir maker, doll and toy maker, barber, garland maker, washerman, tailor, fishing net maker", "source_quote": "Must be actively engaged in one of the 18 specified family-based traditional trades"}, {"text": "Must be practising the trade when registering", "source_quote": "Applicant should be practicing the trade at the time of registration"}, {"text": "No similar government self-employment loan (PMEGP, Mudra, SVANidhi) in the last 5 years", "source_quote": "Should not have availed similar government self-employment loans (e.g., PMEGP, Mudra, SVANidhi) in the last 5 years"}, {"text": "Only one member per family", "source_quote": "Only one member per family is eligible to avail benefits under the scheme"}, {"text": "Government employees and their families are not eligible", "source_quote": "Government employees and their family members are not eligible"}, {"text": "The 18 trades as listed on the page", "source_quote": "Carpenter, Boat maker, Armourer, Black smith, Hammer and Toolkit maker, Lock smith, Sculpture, Gold smith, potter, cobbler, Masions, Basket/Mat/Broom maker/Coir waiver, Doll and Toy maker, Barber, Garland maker, Washerman, Toiler, Fishing Net maker"}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "Trades are not modelled because the occupation field is free text"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('89879b4b-3bbe-5466-85ba-407eb9333ab2', 'pmjdy', 'central', null, 'banking', 'https://wb.gov.in/government-schemes-details-pradhan-mantri-jan-dhan-yojana.aspx', 'sha256:6d08863211137140d6f8bd537dbbf6d14f35976f38ea29b3305aa24be36a6b69', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('89879b4b-3bbe-5466-85ba-407eb9333ab2', 'en', 'Pradhan Mantri Jan Dhan Yojana', 'Zero-balance savings account with a RuPay card, accident cover of about Rs 2 lakh and an overdraft of up to Rs 10,000 for eligible holders.', 'Visit a bank branch or Bank Mitra outlet, fill the PMJDY form and submit KYC documents (or open a Small Account).');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('e316a6ba-8f34-5d5f-b0ef-f26602f28577', '89879b4b-3bbe-5466-85ba-407eb9333ab2', 1, 1, '{"all": [{"field": "age", "op": "gte", "value": 10, "source_quote": "Minimum age:10 years (minors can open accounts with a guardian)"}]}'::jsonb, '[{"text": "Must be an Indian citizen", "source_quote": "Indian Citizen"}, {"text": "Must not already have a basic savings bank account (an existing one can be converted)", "source_quote": "Must not already have a basic savings bank account (or can convert an existing account into a PMJDVaccount)"}, {"text": "Needs basic KYC documents (Aadhaar, voter ID, PAN, etc.)", "source_quote": "Requires basic KYC documents (Aadhaar card, voter ID, PAN, etc.)"}, {"text": "Without KYC documents, a Small Account with limits can be opened", "source_quote": "If KYC documents are not available, a Small Account can be opened with simplified documentation (subject to certain limits)"}, {"text": "Priority to unbanked people, especially in rural areas", "source_quote": "Priority given to unbanked and financially excluded individuals, especially in rural areas"}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "Minors aged 10 and above open the account with a guardian"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('15892c69-8585-5e00-8986-1c678aeb4d86', 'pmjjby', 'central', null, 'insurance', 'https://jansuraksha.gov.in/Files/PMJJBY/English/Rules.pdf', 'sha256:ea728b9fbc659937f2fd5eedb2c1caa3e630beceae199f73dc8d8e0d9d2bbead', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('15892c69-8585-5e00-8986-1c678aeb4d86', 'en', 'Pradhan Mantri Jeevan Jyoti Bima Yojana', 'One-year renewable life cover; premium Rs 436 a year.', 'Join through the bank or post office where you have a savings account, by giving consent for the yearly premium to be auto-debited.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('e074934f-f4bd-52b2-80d8-9764cd7ac426', '15892c69-8585-5e00-8986-1c678aeb4d86', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [18, 50], "source_quote": "in the age group of 18 to 50 years are entitled to join"}]}'::jsonb, '[{"text": "Must hold an individual bank or post office account and consent to auto-debit", "source_quote": "Individual bank/ Post office account holders of the participating banks/ Post office"}]'::jsonb, '["Age is ''age nearer birthday'', so the boundary can differ from age in completed years"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('6e0aac66-708a-5371-892f-79b261d8e9c6', 'pmmvy', 'central', null, 'maternity', 'https://www.spniwcd.wcd.gov.in/uploads/pdf/1710098119_HDEXdpWMb1.pdf', 'sha256:a28b3e0b2eaad46b5de419890d721d6830cd327b80090505416b44c99d640bfd', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('6e0aac66-708a-5371-892f-79b261d8e9c6', 'en', 'Pradhan Mantri Matru Vandana Yojana', 'Rs 5,000 for the first child in two instalments; Rs 6,000 for a second child if she is a girl.', 'An Anganwadi or ASHA worker can fill the form online, or apply on the PMMVY portal.');
insert into public.scheme_documents (scheme_id, doc_key, mandatory, condition) values ('6e0aac66-708a-5371-892f-79b261d8e9c6', 'aadhaar', true, null);
insert into public.scheme_documents (scheme_id, doc_key, mandatory, condition) values ('6e0aac66-708a-5371-892f-79b261d8e9c6', 'bank_account', true, null);
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('284e3c27-4f08-56d3-8b22-84f366d2e98a', '6e0aac66-708a-5371-892f-79b261d8e9c6', 1, 1, '{"all": [{"field": "is_pregnant_or_lactating", "op": "eq", "value": true, "source_quote": "Pregnant Women & Lactating Mothers (PW&LM)"}, {"field": "age", "op": "lt", "value": 55, "source_quote": "less than 55 years at the time of child birth"}, {"any": [{"field": "annual_family_income", "op": "lt", "value": 800000, "source_quote": "Women whose net family income is less than ₹ 8 Lakh per annum"}, {"field": "has_bpl_card", "op": "eq", "value": true, "source_quote": "Women holder of BPL ration Card"}, {"field": "disability_percent", "op": "gte", "value": 40, "source_quote": "Women who are partially (40%) or fully disabled (Divyang Jan)"}, {"field": "caste_category", "op": "eq", "value": "SC", "source_quote": "SC Women"}, {"field": "caste_category", "op": "eq", "value": "ST", "source_quote": "ST Women"}]}]}'::jsonb, '[{"text": "Minimum age is 18 years and 7 months at childbirth (not expressible in whole years)", "source_quote": "The age of beneficiary under PMMVY should be 18 years"}, {"text": "Second-child benefit only if the second child is a girl", "source_quote": "PMMVY benefit given for second child also, if the second child is girl"}, {"text": "Holds an MGNREGA job card", "source_quote": "Women holding MGNREGA Job Card"}, {"text": "Is a woman farmer receiving PM-KISAN", "source_quote": "Women farmers who are beneficiaries under Kisan Samman Nidhi"}, {"text": "Holds an e-Shram card", "source_quote": "Women holding e-Shram card"}, {"text": "Is a PMJAY (Ayushman Bharat) beneficiary", "source_quote": "Women Beneficiaries under Pradhan Mantri Jan Aarogya Yojana (PMJAY) under Ayushman Bharat"}, {"text": "Is a pregnant or lactating Anganwadi worker, helper or ASHA", "source_quote": "Pregnant and Lactating AWWS/ AWHS/ASHAS"}, {"text": "Holds a ration card under the National Food Security Act (NFSA), 2013", "source_quote": "Women Beneficiaries holding Ration card under National Food Security Act (NFSA), 2013"}, {"text": "Must register within 270 days of childbirth", "source_quote": "A beneficiary is eligible to register in PMMVY till 270 days from childbirth"}, {"text": "Must register the pregnancy and complete at least two ante-natal check-ups", "source_quote": "Registration of Pregnancy and at least two Ante-Natal Check-up (ANC) preferably within six months from LMP"}, {"text": "First-child benefit is for the first living child", "source_quote": "Benefits would be disbursed in 2 instalments for 1st living child"}, {"text": "Second-child benefit only for a girl born on or after 1 April 2022", "source_quote": "For beneficiaries of second girl child born on or after 1.04.2022 can apply for benefits"}]'::jsonb, '["Because some qualifying categories are unmodelled, a FAIL on the category group can be a false negative"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('5dde4c52-e033-5291-a15c-a9cb1e6fe247', 'pmsby', 'central', null, 'insurance', 'https://jansuraksha.gov.in/Files/PMSBY/English/Rules.pdf', 'sha256:13091493314dd12610869702822e126c747c846ec13e5419a99fa7e8852cde20', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('5dde4c52-e033-5291-a15c-a9cb1e6fe247', 'en', 'Pradhan Mantri Suraksha Bima Yojana', 'One-year renewable accident cover.', 'Join through the bank or post office where you have a savings account, by giving consent for the yearly premium to be auto-debited.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('1f7c8c11-d2c8-5ef5-876a-ea27f2d74e4d', '5dde4c52-e033-5291-a15c-a9cb1e6fe247', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [18, 70], "source_quote": "aged between 18 years (completed) and 70 years (age nearer birthday)"}]}'::jsonb, '[{"text": "Must hold an individual bank or post office account and consent to auto-debit", "source_quote": "Individual bank/ Post office account holders of participating banks/ Post office"}]'::jsonb, '["Upper age is ''age nearer birthday''"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('0217a9e1-74af-5016-8bf2-ae747555ee4c', 'pmuy', 'central', null, 'household', 'https://wb.gov.in/government-schemes-details-pradhan-mantri-ujjwala-yojana.aspx', 'sha256:80ddd6bda6857209a4181997a9554ae2b4923c004ece56f3249dffb019785b30', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('0217a9e1-74af-5016-8bf2-ae747555ee4c', 'en', 'Pradhan Mantri Ujjwala Yojana', 'Deposit-free LPG connection in the woman''s name, with a free first refill and stove, and refill subsidy by DBT.', 'Apply at an LPG distributor or online on the PMUY or oil company (IOCL, BPCL, HPCL) websites, with the deprivation declaration.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('00bf5c7d-cb04-5f5f-8a34-ac00ec904f7c', '0217a9e1-74af-5016-8bf2-ae747555ee4c', 1, 1, '{"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "The applicant must be a woman who has attained18 years of age."}, {"field": "age", "op": "gte", "value": 18, "source_quote": "The applicant must be a woman who has attained18 years of age."}]}'::jsonb, '[{"text": "No other LPG connection from any oil company in the same household", "source_quote": "There should be no other LPG connection from any Oil Marketing Company (OMC) within the same household."}, {"text": "Must be from a poor household, shown by a deprivation declaration in the set format", "source_quote": "The adult woman must belong to a poor household based on submission of a deprivation declaration (as per prescribed format)."}, {"text": "Must have a valid Aadhaar number", "source_quote": "Applicant must have a valid Aadhaar number (for identificationand subsidy transfer)."}, {"text": "Must have a bank account for DBT", "source_quote": "Must have abank account to receive subsidy through Direct Benefit Transfer (DBT)."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('67c6a979-c946-59a0-b27e-346dda784f33', 'sukanya-samriddhi', 'central', null, 'savings', 'https://wb.gov.in/government-schemes-details-sukanya-samriddhi-yojana.aspx', 'sha256:b77f7e9bd7f774f86cfd8be2d49831e42533c2eccaff5ee159752f1334949547', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('67c6a979-c946-59a0-b27e-346dda784f33', 'en', 'Sukanya Samriddhi Yojana', 'Government-backed savings account for a girl: 8.2% a year now, Rs 250 to Rs 1.5 lakh a year, tax-free, matures after 21 years.', 'A parent or guardian opens it at a post office or authorised bank with the girl''s birth certificate and their own KYC documents.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('966f0ee5-c75a-59c1-aa3e-4776e2a1bd42', '67c6a979-c946-59a0-b27e-346dda784f33', 1, 1, '{"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "The account can be opened in the name of a girl child."}, {"field": "age", "op": "lt", "value": 10, "source_quote": "The girl child should be below 10 years of age at the time of account opening."}]}'::jsonb, '[{"text": "A parent or legal guardian opens and runs the account until the girl can", "source_quote": "The account is opened and operated by the parent or legal guardian until the girl child becomes eligible to operate it herself."}, {"text": "Only one account per girl", "source_quote": "Only one account can be opened in the name of one girl child."}, {"text": "At most two girls per family", "source_quote": "A family can generally open accounts for a maximum of two girl children."}, {"text": "More than two only in special cases such as twins or triplets", "source_quote": "Accounts for more than two girl children may be allowed in special cases such as twins or triplets, subject to required documentation."}, {"text": "Needs the girl''s birth certificate and the guardian''s ID and address proof", "source_quote": "The applicant must submit the birth certificate of the girl child and identity/address proof of the guardian."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('bd14a9ed-ccf8-537b-a1e0-45080f51b10f', 'wb-annapurna', 'state', 'WB', 'women', 'https://wb.gov.in/government-schemes-details-annaapurna-yojana.aspx', 'sha256:f1f01c9d248228438819d47e229837d924ed52b19b5227cd1ae99e57be962ffc', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('bd14a9ed-ccf8-537b-a1e0-45080f51b10f', 'en', 'Annapurna Yojana', 'Rs 3,000 per month.', 'Submit the Family Level Data Collection form at the BDO, SDO or KMC ward office, or online at socialregistry.wb.gov.in.');
insert into public.scheme_documents (scheme_id, doc_key, mandatory, condition) values ('bd14a9ed-ccf8-537b-a1e0-45080f51b10f', 'epic_voter_id', true, null);
insert into public.scheme_documents (scheme_id, doc_key, mandatory, condition) values ('bd14a9ed-ccf8-537b-a1e0-45080f51b10f', 'aadhaar', true, null);
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('f03a80da-2b08-5ba0-9967-0759c666bc66', 'bd14a9ed-ccf8-537b-a1e0-45080f51b10f', 1, 1, '{"all": [{"field": "gender", "op": "eq", "value": "female", "source_quote": "financial assistance to female residents of West Bengal"}, {"field": "age", "op": "between", "value": [25, 60], "source_quote": "between the ages of 25 and 60"}]}'::jsonb, '[{"text": "Must not be in permanent government employment", "source_quote": "must not be any permanent government employment"}, {"text": "Must not be an illegal immigrant", "source_quote": "not an illegal immigrant"}, {"text": "Must not be an income-tax payer", "source_quote": "must not be an income tax payer"}]'::jsonb, '["''Between the ages of 25 and 60'' does not say whether 25 and 60 themselves are included; the rule includes both", "The page does not say whether Annapurna replaces Lakshmir Bhandar, which is no longer listed on wb.gov.in", "Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('2de88a97-380c-553b-a529-b24dac21c4eb', 'wb-bmssy', 'state', 'WB', 'livelihood', 'https://wb.gov.in/government-schemes-details-bina-mulya-samajik-suraksha-yojana.aspx', 'sha256:09265ae7826a2dbdfa677e327a3d54b21cd40f60c7caec4acf2f35ad77b7131f', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('2de88a97-380c-553b-a529-b24dac21c4eb', 'en', 'Bina Mulya Samajik Suraksha Yojana', 'Free cover paid by the state: Rs 50,000 on natural death, up to Rs 2 lakh on accidental death or disability, and provident fund contribution.', 'Apply on the BM-SSY portal or at a Regional Labour Office or Labour Welfare Facilitation Centre in your block or municipality.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('128cfe3a-05fa-5dc5-8b55-0f9a501d2ef5', '2de88a97-380c-553b-a529-b24dac21c4eb', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [18, 60], "source_quote": "Age: 18 to 60 years"}]}'::jsonb, '[{"text": "Must be a resident of West Bengal", "source_quote": "Residency: Must be a resident of West Bengal"}, {"text": "Must be an unorganised-sector worker, including self-employed", "source_quote": "Occupation: Must be an unorganized sector worker (including self-employed)"}, {"text": "The worker''s occupation must be on the scheme''s list (the list is not on the page)", "source_quote": "Category coverage: Worker should fall under list"}, {"text": "Family income up to Rs 6,500 a month, except for construction and transport workers", "source_quote": "Family income within Rs 6500 per month (except construction and transport workers)"}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "The income limit has an exception by occupation, so it is not modelled"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('9e20fb7a-6691-5428-bf29-7d63085614f1', 'wb-jai-johar', 'state', 'WB', 'pension', 'https://wb.gov.in/government-schemes-details-jai-johar-old-age-pensionfor-st-communities.aspx', 'sha256:ca4e291e4ccbd13d134f1eb05d077667bfe1120ed587995f49ad8c8b78e0b409', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('9e20fb7a-6691-5428-bf29-7d63085614f1', 'en', 'Jai Johar (old-age pension for ST communities)', 'Monthly pension by direct bank transfer (amount not stated on the page).', 'Apply at the Gram Panchayat, municipal office, BDO, District Welfare Office or a Common Service Centre.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('f40fa5a3-4141-5441-881d-07101f60609f', '9e20fb7a-6691-5428-bf29-7d63085614f1', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "ST", "source_quote": "Individuals belonging to Scheduled Tribe (ST) category."}, {"field": "age", "op": "gte", "value": 60, "source_quote": "Age of 60 years or above."}]}'::jsonb, '[{"text": "Must be economically disadvantaged with limited or no stable income", "source_quote": "Economically disadvantaged individuals with limited or no stable income."}, {"text": "Must not receive a similar pension under another major government scheme", "source_quote": "Not receiving similar pension benefits under other major government pension schemes"}, {"text": "Must be a resident of West Bengal", "source_quote": "Residents of West Bengal."}]'::jsonb, '["The page says eligible beneficiaries ''generally include'' these groups, so the list may not be complete or strict", "''As per applicable guidelines'': the guidelines themselves are not on the page", "No income limit is given for ''economically disadvantaged''", "Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('8b349bdf-785d-5fc0-aa3f-bc1738c712b3', 'wb-medhashree', 'state', 'WB', 'education', 'https://wb.gov.in/government-schemes-details-west-bengal-medhashree-scheme.aspx', 'sha256:3f757ab13e51d8647441e8ce61ed13e9736c0a1899ca56040bfba5e9b4a127c1', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('8b349bdf-785d-5fc0-aa3f-bc1738c712b3', 'en', 'Medhashree', 'Rs 800 per year, renewable up to Class VIII.', 'Students are identified by their school, which applies on the official portal.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('89f74ae7-ed50-5004-8869-72059c5a1dc7', '8b349bdf-785d-5fc0-aa3f-bc1738c712b3', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "OBC", "source_quote": "Must belong to the OBC category."}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "Must be studying in Classes V-VIII"}, {"field": "education_level", "op": "in", "value": ["class_5", "class_6", "class_7", "class_8"], "source_quote": "Must be studying in Classes V-VIII"}, {"field": "annual_family_income", "op": "lte", "value": 250000, "source_quote": "Annual family income should generally not exceed Rs 2.5 lakh."}]}'::jsonb, '[{"text": "Described as for ''meritorious'' students (no merit criterion is given)", "source_quote": "financial assistance to meritorious students"}, {"text": "School must be government, government-aided or government-recognised", "source_quote": "in a government, government-aided, or government-recognized school"}, {"text": "Must not receive another similar scholarship", "source_quote": "Student should not be receiving any other similar scholarship."}, {"text": "Must have a valid bank account", "source_quote": "Must have a valid bank account."}, {"text": "Must be a permanent resident of West Bengal", "source_quote": "The applicant must be a permanent resident of West Bengal."}]'::jsonb, '["Income ''should generally not exceed Rs 2.5 lakh'': ''generally'' means the limit may not be strict", "The intro says the scheme supports ''higher education'' and ''meritorious'' students, but the eligibility list says Classes V to VIII", "Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('ae7d0043-d612-548f-b591-647581f71487', 'wb-migrant-worker', 'state', 'WB', 'livelihood', 'https://wb.gov.in/government-schemes-details-west-bengal-migrant-worker-welfare-scheme.aspx', 'sha256:d4b07e6ec8a2da38a78549a4c139b5d5a8c0514b5c584c512e2c04635369719d', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('ae7d0043-d612-548f-b591-647581f71487', 'en', 'West Bengal Migrant Worker Welfare Scheme', 'Rs 50,000 on natural death, Rs 2 lakh on accidental death, Rs 25,000 to bring the body home, and Rs 50,000 to Rs 1 lakh for disability.', 'Register on the Karmasathi Parijayee Shramik Portal with your mobile number to get an MWIN, then file claims there.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('5f274e05-f920-584e-adcd-9f4a14000e7c', 'ae7d0043-d612-548f-b591-647581f71487', 1, 1, '{"all": [{"field": "age", "op": "between", "value": [14, 60], "source_quote": "Between 14 and 60 years of age"}]}'::jsonb, '[{"text": "Must be a resident of West Bengal", "source_quote": "Must be a resident of West Bengal"}, {"text": "Must work, or be likely to work, outside West Bengal (other states or abroad)", "source_quote": "Must be employed or likely to be employed outside West Bengal (in other states/UTs or abroad)."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('942ace53-786c-5408-835e-2ae49b249caa', 'wb-pre-matric', 'state', 'WB', 'education', 'https://wb.gov.in/government-schemes-details-pre-matric-scholarship-for-sc-st-obc-students.aspx', 'sha256:84a96e570cd544bea06c72b35e02e45a12b0c91ba0461737ba98794ff969ebb4', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('942ace53-786c-5408-835e-2ae49b249caa', 'en', 'Pre-Matric Scholarship for SC, ST and OBC Students (West Bengal)', 'Monthly maintenance allowance, tuition and compulsory fees, and extra help for hostel students and students with disabilities.', 'Register on oasis.wb.gov.in (OTR ID), apply online with caste and income certificates, and the school forwards it for verification.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('9352f9a8-3aca-5055-9c6e-5296e89f21f6', '942ace53-786c-5408-835e-2ae49b249caa', 1, 1, '{"all": [{"field": "caste_category", "op": "in", "value": ["SC", "ST", "OBC"], "source_quote": "Must belong to SC/ST/OBC community and possess a valid caste certificate."}, {"any": [{"field": "caste_category", "op": "eq", "value": "OBC", "source_quote": "varies slightly for OBC depending on scheme/state"}, {"field": "annual_family_income", "op": "lte", "value": 250000, "source_quote": "Rs 2.5 lakh for SC/ST students"}]}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "Must be a regular/full-time student enrolled in school."}]}'::jsonb, '[{"text": "Must study in a recognised school; the class range is generally 9 to 10, and 1 to 10 in some variants", "source_quote": "Studying in a recognized school (generally Class 9 - 10 for SC/ST/OBC schemes;"}, {"text": "OBC students have their own income limit, which the page does not give", "source_quote": "Annual family income limit should not exceed: Rs 2.5 lakh for SC/ST students (varies slightly for OBC depending on scheme/state)."}, {"text": "Renewals need a pass in the previous exam", "source_quote": "Progression requirement: Students should have passed the previous examination (for renewal cases)."}, {"text": "Must not get another scholarship for the same purpose", "source_quote": "Only one scholarship at a time: Student should not be availing another scholarship for the same purpose."}, {"text": "Must be domiciled in West Bengal", "source_quote": "Domicile requirement: Must belong to the state/UT from where applying."}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "The class range is not fixed on the page (Class 9-10 generally, Class 1-10 in some variants), so it is not modelled", "The OBC income limit is not stated, so OBC students are not income-checked here"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('371dc8e9-80c5-5ef9-85ec-aa3499bc7900', 'wb-shikshasree', 'state', 'WB', 'education', 'https://wb.gov.in/government-schemes-details-west-bengal-shikshasree-scheme.aspx', 'sha256:b7cd9de64055473cacec64cb8d80b4c246cfcf04102a73c9805f0bfe2af4f738', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('371dc8e9-80c5-5ef9-85ec-aa3499bc7900', 'en', 'Shikshasree', 'Rs 800 per year for students in Classes V to VIII.', 'Apply through the student''s school.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('76f81838-0292-57d9-b449-8246f6cc71d1', '371dc8e9-80c5-5ef9-85ec-aa3499bc7900', 1, 1, '{"all": [{"field": "caste_category", "op": "in", "value": ["SC", "ST"], "source_quote": "Must belong to the Scheduled Caste (SC) or Scheduled Tribe (ST) category."}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "Must be studying in Classes V-VIII"}, {"field": "education_level", "op": "in", "value": ["class_5", "class_6", "class_7", "class_8"], "source_quote": "Must be studying in Classes V-VIII"}, {"field": "annual_family_income", "op": "lte", "value": 250000, "source_quote": "Annual family income should generally not exceed Rs 2.5 lakh."}]}'::jsonb, '[{"text": "School must be government, government-aided or government-recognised", "source_quote": "in a government, government-aided, or government-recognized school"}, {"text": "Must not receive another similar scholarship", "source_quote": "Student should not be receiving any other similar scholarship."}, {"text": "Must have a valid bank account", "source_quote": "Must have a valid bank account."}, {"text": "Must be a permanent resident of West Bengal", "source_quote": "The applicant must be a permanent resident of West Bengal."}]'::jsonb, '["Income ''should generally not exceed Rs 2.5 lakh'': ''generally'' means the limit may not be strict", "Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('5975d2df-401a-5f12-81e4-628898960be9', 'wb-student-credit-card', 'state', 'WB', 'education', 'https://wb.gov.in/government-schemes-details-west-bengal-student-credit-card-scheme.aspx', 'sha256:4630880363e44425dc7b7b90ec87edcd8fcea8f55355b567f8f8a8d84ce110ee', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('5975d2df-401a-5f12-81e4-628898960be9', 'en', 'West Bengal Student Credit Card', 'Collateral-free education loan up to Rs 10 lakh at about 4% simple interest, repayable over up to 15 years.', 'Register on the WBSCC portal, apply with admission and ID documents; the institution and Higher Education Department verify it before the bank sanctions.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('ee0de9e0-08dd-5481-85dd-9340c1d6c11c', '5975d2df-401a-5f12-81e4-628898960be9', 1, 1, '{"all": [{"field": "age", "op": "lte", "value": 40, "source_quote": "Must be 40 years or below at the time of application"}, {"field": "is_student", "op": "eq", "value": true, "source_quote": "Must be enrolled in a recognized educational institution (India or abroad)"}]}'::jsonb, '[{"text": "Must have lived in West Bengal for ten years or more", "source_quote": "Must be a resident of West Bengal for ten years or more"}, {"text": "Must have completed at least Class IX (Madhyamik or equivalent)", "source_quote": "Should have completed at least Class IX (Madhyamik or equivalent)"}, {"text": "Must have admission in an eligible course (school, UG, PG or professional)", "source_quote": "Must have secured admission in an eligible course (school, UG, PG, or professional)"}, {"text": "Needs a co-borrower, usually a parent or guardian", "source_quote": "Co-borrower required (usually a parent/guardian)"}, {"text": "Neither the student nor the co-borrower may be in default on a bank loan", "source_quote": "Applicant or Co-borrower must not be in default of any bank loan"}, {"text": "Only one card per student", "source_quote": "Only one student credit card per student is allowed"}, {"text": "Must apply on the official portal with valid documents", "source_quote": "Must apply through the official online portal with valid documents"}]'::jsonb, '["Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines", "''Class IX (Madhyamik or equivalent)'' is unclear, because Madhyamik is the Class 10 exam, so the class is not modelled"]'::jsonb, true);
insert into public.schemes (id, slug, level, state, category, official_url, source_hash, last_checked, status) values ('3141e820-3f50-5d51-bb90-07fd6297bd9e', 'wb-taposili-bandhu', 'state', 'WB', 'pension', 'https://wb.gov.in/government-schemes-details-taposili-bandhu-scheme.aspx', 'sha256:c381aa6c456afb959f19dc0442b21023600b0dfdd61f6379e7f25d8129bfe12d', '2026-10-19', 'live');
insert into public.scheme_texts (scheme_id, lang, title, benefit, how_to_apply) values ('3141e820-3f50-5d51-bb90-07fd6297bd9e', 'en', 'Taposili Bandhu', 'Rs 1,000 per month pension by direct bank transfer.', 'Collect the form from the BDO or municipality office, attach documents and submit it to the local authority.');
insert into public.scheme_rule_versions (id, scheme_id, version, rule_format_version, eligibility, unmodelled, ambiguous, source_quote_check_passed) values ('a402d578-accc-55be-b157-64c7ab256ac8', '3141e820-3f50-5d51-bb90-07fd6297bd9e', 1, 1, '{"all": [{"field": "caste_category", "op": "eq", "value": "SC", "source_quote": "Must belongto the Scheduled Caste (SC) community"}, {"field": "age", "op": "gte", "value": 60, "source_quote": "Must be 60 years of age or above"}]}'::jsonb, '[{"text": "Must be economically disadvantaged (not defined on the page)", "source_quote": "who are economically disadvantaged"}, {"text": "Must not receive any other government pension", "source_quote": "Should not be abeneficiary of any other government pension scheme"}, {"text": "Must have a valid bank account for DBT", "source_quote": "Must have a valid bank account for Direct Benefit Transfer (DBT)"}, {"text": "Must be a permanent resident of West Bengal", "source_quote": "Applicant must be a permanent resident of West Bengal"}]'::jsonb, '["''Economically disadvantaged'' has no income limit on the page", "Source is a short summary by the Department of Information & Cultural Affairs on wb.gov.in, not the scheme''s own guidelines"]'::jsonb, true);
